import { useEffect, useMemo, useState } from 'react';
import type { EventData, Person, UpdateEvent } from '../core/types';
import { IMPORT_FIELDS, FIELD_LABELS, parseDelimited, readImportFile, previewImport, applyImport, createTemplate, createCsvTemplate, guessMapping, analyzeImportImpact, reviewImport } from '../io/imports';
import type { ImportTable, ColumnMapping } from '../io/imports';
import { downloadBlob } from '../io/exports';
type Kind='roster'|'availability'|'demand';
export default function ImportPanel({event,onChange,readOnly=false}:{event:EventData;onChange:UpdateEvent;readOnly?:boolean}){
 const [kind,setKind]=useState<Kind>('roster'),[mode,setMode]=useState<'append'|'update'|'replace'>('append'),[paste,setPaste]=useState(''),[table,setTable]=useState<ImportTable|null>(null),[mapping,setMapping]=useState<ColumnMapping>({}),[error,setError]=useState(''),[busy,setBusy]=useState(false);
 const preview=useMemo(()=>table?previewImport(event,kind,table,mapping):null,[event,kind,table,mapping]);
 const [reviewed,setReviewed]=useState(false);
 useEffect(()=>setReviewed(false),[table,mapping,mode]);
 const review=preview?reviewImport(preview):null;
 const needsReview=!!review&&(review.ignored.length>0||mode!=='append');
 const impact=useMemo(()=>preview?analyzeImportImpact(event,preview,mode):null,[event,preview,mode]);
 const load=(t:ImportTable)=>{setTable(t);setMapping(guessMapping(kind,t.headers));setError('');};
 return <section className="panel"><details><summary>CSV / Excel 가져오기 · 입력 서식</summary><p>파일은 이 브라우저에서 처리합니다. 열과 오류를 확인한 뒤 적용하세요. 업로드만으로 기존 자료를 바꾸지 않습니다.</p><div className="toolbar"><label>입력 자료<select value={kind} onChange={x=>{setKind(x.target.value as Kind);setTable(null)}}><option value="roster">참여자 명단</option><option value="availability">참여 가능시간</option><option value="demand">장소별 필요 인원</option></select></label><button className="button secondary" disabled={busy} onClick={async()=>{setBusy(true);try{downloadBlob(await createTemplate(kind,event),`${kind}-입력서식.xlsx`)}catch(x){setError(String(x))}finally{setBusy(false)}}}>XLSX 입력 서식 받기</button><button className="button secondary" onClick={()=>downloadBlob(createCsvTemplate(kind),`${kind}-입력서식.csv`)}>CSV 입력 서식 받기</button><label>CSV / XLSX 파일<input type="file" accept=".csv,.tsv,.xlsx" disabled={readOnly} onChange={async x=>{const f=x.target.files?.[0];if(!f)return;setBusy(true);try{load(await readImportFile(f))}catch(err){setError(String(err))}finally{setBusy(false);x.target.value=''}}}/></label></div><label>엑셀 표 붙여넣기 (첫 행은 열 제목)<textarea rows={4} disabled={readOnly} value={paste} onChange={x=>setPaste(x.target.value)} placeholder={'이름\t소속\n가상 참여자\t운영팀'}/></label><button className="button secondary" disabled={!paste||readOnly} onClick={()=>{try{load(parseDelimited(paste))}catch(x){setError(String(x))}}}>붙여넣기 미리보기</button>
 {error&&<p role="alert" className="notice error-text">{error}</p>}
 {table&&preview&&<div className="stack"><h3>가져오기 검토 · {table.rows.length}행</h3><p>아래 연결과 실제 반영 결과를 확인한 뒤 적용하세요.</p>{review&&<div className="notice" role="status"><strong>정상 반영 가능 {review.validRows}행 · 오류 {review.errorRows}행 · 자동 해석 {review.normalizedRows}행 · 미반영 {review.ignored.length}개 열</strong><p>{review.ignored.length?`확인 필요: ${review.ignored.join(', ')} 열은 저장되지 않습니다. 연결을 지정하거나 제외 사실을 확인하세요.`:'모든 원본 열이 연결되었습니다.'}</p>{review.duplicate.length>0&&<p className="error-text">오류: {review.duplicate.join(', ')} 열이 여러 필드에 중복 연결되었습니다.</p>}<ul>{review.columns.map(c=><li key={c.header}>{c.header} → {c.fields.length?c.fields.map(f=>FIELD_LABELS[f]).join(', '):'미반영'}</li>)}</ul></div>}<div className="form-grid">{IMPORT_FIELDS[kind].map(field=><label key={field}>{FIELD_LABELS[field]||field}<select value={mapping[field]??''} onChange={x=>setMapping({...mapping,[field]:x.target.value})}><option value="">연결 안 함</option>{table.headers.map((h,i)=><option key={i} value={h}>{h}</option>)}</select></label>)}</div><details><summary>원본 표 보기 (최대 8행)</summary><div className="table-wrap"><table><thead><tr>{table.headers.map((h,i)=><th key={i}>{h}</th>)}</tr></thead><tbody>{table.rows.slice(0,8).map((row,i)=><tr key={i}>{row.map((c,j)=><td key={j}>{String(c??'')}</td>)}</tr>)}</tbody></table></div></details>{kind==='roster'&&<div className="table-wrap"><table aria-label="실제 반영될 명단"><thead><tr><th>이름</th><th>소속/팀</th><th>해석된 자격</th></tr></thead><tbody>{(preview.records as Person[]).slice(0,32).map(p=><tr key={p.id}><td>{p.name}</td><td>{p.team||'—'}</td><td>{p.tags.length?p.tags.map(tag=><span className="pill" key={tag}>{tag}</span>):'없음'}</td></tr>)}</tbody></table><p className="small">실제 반영 결과 중 최대 32명 표시 · 자격은 쉼표, 세미콜론, 줄바꿈으로 구분합니다.</p></div>}<label>적용 방식<select value={mode} onChange={x=>setMode(x.target.value as typeof mode)}><option value="append">기존 자료에 추가</option><option value="update">기존 ID 기준 업데이트</option><option value="replace">해당 자료 전체 교체</option></select></label>{preview.errors.length>0?<ul className="issue-list error-text">{preview.errors.slice(0,50).map((v,i)=><li key={i}>{v.row}행: {v.message}</li>)}</ul>:<p>{needsReview?'확인 필요 항목을 검토하세요.':'정상 반영 준비 완료'} · {preview.records.length}개 항목</p>}{impact&&<div className="notice">{impact.messages.map((m,i)=><p key={i}>{m}</p>)}<p>영향받는 기존 배정 {impact.affectedAssignmentIds.length}건</p></div>}{needsReview&&<label className="check"><input type="checkbox" checked={reviewed} onChange={x=>setReviewed(x.target.checked)}/>미반영 열과 기존 자료에 미치는 영향을 확인했습니다</label>}<button className="button primary" disabled={readOnly||preview.errors.length>0||!preview.records.length||!!review?.duplicate.length||(needsReview&&!reviewed)} onClick={()=>{try{if(mode==='replace'&&!window.confirm('표시된 영향을 확인했나요? 이 자료 전체를 교체합니다. 기존 배정에 오류가 생기면 수정 목록으로 표시됩니다.'))return;const applied=applyImport(event,preview,mode);onChange(applied.event,'파일 자료 가져오기');setError('적용했습니다. 배치표의 수정 필요 목록을 확인하세요.');setTable(null);setPaste('')}catch(x){setError(String(x))}}}>미리보기 내용 적용</button></div>}
 </details></section>;
}
