import Issues from './Issues';
import { useEffect, useMemo, useRef, useState } from 'react';
import { createPortal } from 'react-dom';
import { toPng } from 'html-to-image';
import type { EventData, Shortage, UpdateEvent } from '../core/types';
import { validateEvent } from '../core/validate';
import { dateOf, toMinute } from '../core/time';
import { confirmEvent, changedPersonIds, assignmentChanges } from '../core/revisions';
import { buildReport, createWorkbook, downloadBlob, reportFilename, toCsv, type Report, type ReportKind, type ReportOptions } from '../io/exports';

function readable(report:Report){
 if(report.headers[0]==='날짜') {
  const columns=[{index:5,label:'장소'},{index:6,label:'담당자'},{index:7,label:'담당 유형'},{index:8,label:'공개 메모'},...(report.headers.length>9?[{index:9,label:'운영자 메모'}]:[])].filter(c=>report.rows.some(r=>r[c.index]&&r[c.index]!=='미지정'));
  return {headers:['일시','프로그램',...columns.map(c=>c.label)],rows:report.rows.map(r=>[`${r[0]} ${r[1]}–${r[0]===r[2]?'':r[2]+' '}${r[3]}`,r[4],...columns.map(c=>r[c.index])])};
 }
 return {headers:['이름','소속/팀','일시','장소','역할','분','상태'],rows:report.rows.map(r=>[r[1],r[2],r[3]?`${r[3]} ${r[4]}–${r[3]===r[5]?'':r[5]+' '}${r[6]}`:'—',r[7],r[8],r[9],r[10]])};
}
function PrintTable({report,event,page=1,pages=1}:{report:Report;event:EventData;page?:number;pages?:number}){
 const display=readable(report);
 const widths=report.headers[0]==='날짜'?display.headers.map(()=>100/display.headers.length):[17,14,25,14,14,7,9];
 const metadata=<><div className="print-title">{event.logoDataUrl&&<img src={event.logoDataUrl} alt="기관 로고" className="print-logo"/>}<div><p>{event.organization||'행사 시간표 제작기'}</p><h1>{event.name}</h1><h2>{report.title}</h2></div><strong className="print-state">{report.statusLabel}<br/>v{event.edition}</strong></div><p className="print-meta">행사일 {event.days.map(d=>d.date).join(' / ')} · Asia/Seoul · 생성 {new Date(report.generatedAt).toLocaleString('ko-KR')}</p></>;
 return <section className="print-page"><table className={'print-table '+(report.headers[0]==='날짜'?'program-table':'staff-table')}><colgroup>{widths.map((w,i)=><col key={i} style={{width:w+'%'}}/>)}</colgroup><thead><tr className="report-metadata"><th colSpan={display.headers.length}>{metadata}</th></tr><tr>{display.headers.map(h=><th key={h} scope="col">{h}</th>)}</tr></thead><tbody>{display.rows.length?display.rows.map((row,i)=><tr key={i}>{row.map((c,j)=><td key={j}>{c}</td>)}</tr>):<tr><td colSpan={display.headers.length}>이 범위에 배정된 일정이 없습니다.</td></tr>}</tbody></table><div className="print-foot"><span>{report.headers[0]==='날짜'?`진행 순서 ${report.rows.length}개`:`출력 전체 합계 ${report.totalMinutes.toLocaleString()}분`}{report.validation.shortageMinutes>0?` · 행사 전체 부족 ${report.validation.shortageMinutes}인분`:''}</span><span>표 {page} / {pages}</span></div>{report.statusLabel!=='확정'&&<p className="print-warning">{report.statusLabel} · 확정 전 일정은 바뀔 수 있습니다. {report.validation.errors.length?`행사 전체 검사 오류 ${report.validation.errors.length}건.`:''}</p>}</section>;
}
export default function Review({event:e,onChange,onBackup,readOnly=false,onNavigate,onSlot}:{event:EventData;onChange:UpdateEvent;onBackup:()=>void;readOnly?:boolean;onNavigate:(step:number,personId?:string)=>void;onSlot:(s:Shortage)=>void}){
 const [kind,setKind]=useState<ReportKind>(e.mode==='program'?'program':'full'),[date,setDate]=useState(''),[location,setLocation]=useState(''),[roleFilter,setRoleFilter]=useState(''),[person,setPerson]=useState(''),[team,setTeam]=useState(''),[internal,setInternal]=useState(false),[paper,setPaper]=useState('A4'),[orientation,setOrientation]=useState('landscape'),[snapshot,setSnapshot]=useState(''),[notice,setNotice]=useState(''),[busy,setBusy]=useState(false),[rangeStart,setRangeStart]=useState(''),[rangeEnd,setRangeEnd]=useState('');
 const output=useMemo(()=>{const s=e.snapshots.find(s=>s.id===snapshot);return s?{...s.data,snapshots:e.snapshots.filter(x=>x.version<=s.version)} as EventData:e},[e,snapshot]);
 const options:ReportOptions={kind,date:date||undefined,locationId:location||undefined,roleId:roleFilter||undefined,personIds:person?[person]:team?output.people.filter(p=>p.team===team).map(p=>p.id):undefined,internal};
 if(date&&rangeStart&&rangeEnd){try{const start=toMinute(date,rangeStart),end=toMinute(date,rangeEnd);if(end>start)options.range={start,end}}catch{ /* no invalid range passed */ }}
 const rangeError=(rangeStart||rangeEnd)&&(!date||!rangeStart||!rangeEnd||rangeEnd<=rangeStart)?'시간 범위를 지정하려면 날짜와 시작·종료를 모두 선택하고 종료를 시작보다 늦게 입력하세요.':'';
 const report=buildReport(output,options),validation=useMemo(()=>validateEvent(e),[e]);
 useEffect(()=>{const previous=document.title;document.title=reportFilename(output,options,'pdf').replace(/\.pdf$/,'');return()=>{document.title=previous}},[output.name,output.edition,kind,date,location,roleFilter,person,team,internal]);
 const previewRef=useRef<HTMLDivElement>(null);
 const pages=useMemo(()=>{const map=new Map<string,typeof report.rows>();for(const row of report.rows){const group=String(row[report.headers[0]==='날짜'?0:3]||'배정 없음')+(['person','changed'].includes(kind)?'|'+row[0]:'');map.set(group,[...(map.get(group)||[]),row]);}const groups:typeof report[]=[];for(const rows of map.values())groups.push({...report,title:report.title+(['person','changed'].includes(kind)?' · '+rows[0][1]:''),rows});return groups.length?groups:[report]},[JSON.stringify(report.rows),paper,orientation,report.title,report.statusLabel,report.totalMinutes]);
 const exportFile=async(fn:()=>Promise<void>)=>{setBusy(true);setNotice('출력 파일을 만드는 중…');try{await fn();setNotice('파일을 생성했습니다. 다운로드한 파일을 확인하세요.')}catch(err){setNotice('출력에 실패했습니다: '+String(err))}finally{setBusy(false)}};
 const changes=assignmentChanges((e.status==='confirmed'?e.snapshots.at(-2):e.snapshots.at(-1))?.data.assignments||[],e.assignments);
 return <div className="stack">
  <section className="panel no-print"><div className="section-head"><div><p className="eyebrow">{e.mode==='program'?'03':'05'} / 확인·출력</p><h2>마지막 확인, 그리고 함께 나눌 일정표.</h2></div><span className="pill">{e.status==='confirmed'?'확정본':'초안'}</span></div><div className="metrics"><div><strong>{validation.errors.length}</strong><span>확정을 막는 오류</span></div>{(e.mode!=='program'||validation.shortageMinutes>0)&&<div><strong>{validation.shortageMinutes}</strong><span>부족 인분</span></div>}<div><strong>{validation.warnings.length}</strong><span>검토할 주의</span></div><div><strong>{e.mode==='program'?e.programs.length:Object.values(validation.personMinutes).reduce((a,b)=>a+b,0)}</strong><span>{e.mode==='program'?'진행 순서':'전체 배정 분'}</span></div></div>
   <p className="notice">{validation.errors.length||validation.shortageMinutes||validation.shortages.some(s=>s.leaderMissing)?'오류·부족을 해결해야 확정할 수 있습니다. 현재 상태는 미완성 초안으로 저장·출력할 수 있습니다.':e.mode==='program'?'시간과 진행 순서를 검토한 뒤 확정하세요.':'필수 검사와 인원 충족을 확인했습니다. 내용을 검토한 뒤 확정하세요.'}</p>
   {(validation.errors.length>0||validation.shortages.length>0)&&<Issues event={e} validation={validation} onSlot={onSlot} onNavigate={onNavigate}/>}
   {validation.warnings.length>0&&<ul className="issue-list">{validation.warnings.map((x,i)=><li key={i}>주의 · {x.message}</li>)}</ul>}
   <div className="toolbar"><button className="button primary" disabled={readOnly||validation.errors.length>0||validation.shortageMinutes>0||validation.shortages.some(s=>s.leaderMissing>0)} onClick={()=>{try{onChange(confirmEvent(e),'확정본 저장');setNotice('확정본을 저장했습니다. 수정하려면 새 개정 초안을 만드세요.')}catch(err){setNotice(String(err))}}}>확정본 저장</button><button className="button secondary" onClick={onBackup}>전체 JSON 백업</button></div><p className="small muted">전체 백업에는 명단·가능시간·운영자 내부메모가 포함됩니다. 공개 배포용 파일과 구분해서 전달하세요.</p>
   {e.snapshots.length>0&&<details><summary>개정 변경 내역 · 바뀐 참여자 {changedPersonIds(e).length}명</summary><p>추가 {changes.added.length}건 · 제거 {changes.removed.length}건. 아래에서 ‘변경된 사람 일정표’를 선택해 수정본만 출력할 수 있습니다.</p><ul>{changes.removed.slice(0,60).map(a=><li key={'r'+a.id}>제거 · {e.people.find(p=>p.id===a.personId)?.name||'삭제된 참여자'} · {dateOf(a.start)}</li>)}{changes.added.slice(0,60).map(a=><li key={'a'+a.id}>추가 · {e.people.find(p=>p.id===a.personId)?.name} · {dateOf(a.start)}</li>)}</ul></details>}
   <details><summary>개인별 시간 합계 · 장소별 충족률</summary><div className="table-wrap"><table><thead><tr><th>참여자</th>{[...new Set(Object.values(validation.dailyMinutes).flatMap(v=>Object.keys(v)))].sort().map(d=><th key={d}>{d}</th>)}<th>총 분</th></tr></thead><tbody>{e.people.map(p=><tr key={p.id}><th>{p.alias||p.name} {p.team}</th>{[...new Set(Object.values(validation.dailyMinutes).flatMap(v=>Object.keys(v)))].sort().map(d=><td key={d}>{validation.dailyMinutes[p.id]?.[d]||0}</td>)}<td>{validation.personMinutes[p.id]||0}</td></tr>)}</tbody></table></div><ul>{Object.entries(validation.locationStats).map(([id,v])=><li key={id}>{e.locations.find(l=>l.id===id)?.name}: {v.requiredMinutes?Math.round(v.coveredMinutes/v.requiredMinutes*100):100}% 충족 · 부족 {v.shortageMinutes}인분</li>)}</ul></details>
  </section>
  <section className="panel no-print"><h3>출력 범위와 형식</h3><div className="form-grid"><label>출력 종류<select value={kind} onChange={x=>setKind(x.target.value as ReportKind)}><option value="full">전체 인력 배치표</option><option value="person">개인별 일정표</option><option value="location">장소·역할별 운영표</option><option value="program">행사 진행 시간표</option><option value="changed">변경된 사람 일정표</option></select></label><label>출력 날짜<select value={date} onChange={x=>setDate(x.target.value)}><option value="">전체 날짜 (날짜별 페이지)</option>{[...new Set([...output.days.map(d=>d.date),...output.assignments.flatMap(a=>[dateOf(a.start),dateOf(a.end-1)])])].sort().map(d=><option key={d}>{d}</option>)}</select></label><label>출력 장소<select value={location} onChange={x=>setLocation(x.target.value)}><option value="">모든 장소</option>{output.locations.map(l=><option key={l.id} value={l.id}>{l.name}</option>)}</select></label><label>출력 역할<select value={roleFilter} onChange={x=>setRoleFilter(x.target.value)}><option value="">모든 역할</option>{output.roles.map(r=><option key={r.id} value={r.id}>{r.name}</option>)}</select></label><label>출력 참여자<select value={person} onChange={x=>setPerson(x.target.value)}><option value="">전체 참여자</option>{output.people.map(p=><option key={p.id} value={p.id}>{p.alias||p.name} · {p.team}</option>)}</select></label><label>출력 팀<select value={team} onChange={x=>setTeam(x.target.value)}><option value="">전체 팀</option>{[...new Set(output.people.map(p=>p.team))].filter(Boolean).map(t=><option key={t}>{t}</option>)}</select></label><label>표 버전<select value={snapshot} onChange={x=>setSnapshot(x.target.value)}><option value="">현재 작업본 v{e.edition}</option>{e.snapshots.map(s=><option key={s.id} value={s.id}>확정본 v{s.version} · {new Date(s.confirmedAt).toLocaleDateString('ko-KR')}</option>)}</select></label><label>용지<select value={paper} onChange={x=>setPaper(x.target.value)}><option>A4</option><option>A3</option></select></label><label>용지 방향<select value={orientation} onChange={x=>setOrientation(x.target.value)}><option value="landscape">가로</option><option value="portrait">세로</option></select></label></div><details><summary>시간 범위 · 내부용 출력</summary><div className="toolbar"><label>범위 시작<input type="time" value={rangeStart} onChange={x=>setRangeStart(x.target.value)}/></label><label>범위 종료<input type="time" value={rangeEnd} onChange={x=>setRangeEnd(x.target.value)}/></label><label className="check"><input type="checkbox" checked={internal} onChange={x=>setInternal(x.target.checked)}/>운영자 메모 포함 (내부용)</label></div><p className="muted">날짜를 선택한 뒤 같은 날짜 안의 시간 범위를 지정하세요. 날짜를 넘는 범위는 날짜별로 출력하세요.</p></details><div className="toolbar"><button className="button primary" disabled={!!rangeError} onClick={()=>window.print()}>인쇄 / PDF로 저장</button><button className="button secondary" disabled={busy||!!rangeError} onClick={()=>void exportFile(async()=>downloadBlob(await createWorkbook(output,options),reportFilename(output,options,'xlsx')))}>XLSX 내려받기</button><button className="button secondary" disabled={busy||!!rangeError} onClick={()=>downloadBlob(new Blob([toCsv([report.headers,...report.rows])],{type:'text/csv;charset=utf-8'}),reportFilename(output,options,'csv'))}>CSV 내려받기</button><button className="button secondary" disabled={busy||!!rangeError} onClick={()=>void exportFile(async()=>{if(!date)throw new Error('PNG는 출력 날짜를 먼저 선택하세요.');if(report.rows.length>100)throw new Error('이미지가 너무 큽니다. 사람·장소·시간 범위를 줄여 100행 이하로 선택하세요.');const node=previewRef.current;if(!node)throw new Error('미리보기를 찾지 못했습니다.');const width=Math.ceil(Math.max(node.scrollWidth,node.getBoundingClientRect().width))+4,height=node.scrollHeight+4;if(width>4096||height>10000)throw new Error('이미지가 너무 큽니다. 시간·참여자 범위를 줄여 주세요.');const data=await toPng(node,{backgroundColor:'#ffffff',pixelRatio:1.5,width,height,style:{width:width+'px',maxWidth:'none',height:'auto',overflow:'visible'}});const blob=await (await fetch(data)).blob();downloadBlob(blob,reportFilename(output,options,'png'));})}>PNG 이미지 저장</button></div>{rangeError&&<p role="alert" className="notice error-text">{rangeError}</p>}{notice&&<p role="status" className="notice">{notice}</p>}
  </section>
  <div className="print-preview-wrap no-print"><div className="section-head"><h3>출력 미리보기</h3><span className="muted">{report.headers[0]==='날짜'?`${report.rows.length}개 진행 순서`:`${report.rows.length}행 · ${report.totalMinutes}분`}</span></div><div ref={previewRef} className="print-preview"><PrintTable report={report} event={output}/></div></div>
  {createPortal(<div className="print-root"><style>{`@media print { @page { size: ${paper} ${orientation}; margin: 12mm; } }`}</style>{pages.map((p,i)=><PrintTable key={i} report={p} event={output} page={i+1} pages={pages.length}/>)}</div>,document.body)}
 </div>;
}
